def prose(s):return re.sub(r'\s+',' ',re.sub(r'\$\$.*?\$\$|\$[^$]*\$','',s,flags=re.S)).strip()
prosechecks=[]
for r in replays:
 p=r['generation']['template'];eq=prose(r['question'][':question/worked-solution'])==prose(srcidx[p][':question/worked-solution']);assert eq;prosechecks.append({'profile':p,'solution_prose_matches_source':eq})
save('scope-results.json',{'passed':True,'source_solution_prose':prosechecks,'tested_count':110,'easy_workload':'Two equations, two x/y coefficient columns plus RHS column; 70 new sample records, five batch records, easy source replays and pairs inspected','moderate_workload':'Two or three equations, three x/y/z coefficient columns plus RHS; 28 new records checked','operators':'Addition/subtraction, integer scalar coefficients, equality and matrices only; no solving or row reduction','response':'One five-choice radio field throughout','limits':'Coverage omissions and overfixed signs fail source/variety separately; this check only certifies no added prerequisites or workload in tested outputs.'})
